import{_ as o,a0 as r,w as s,s as p,ao as l,I as i,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver","title":"Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單","tag":"201508","desc":""},"relativePath":"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver.md","filePath":"[post].md"}'),d={name:"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver.md"};function b(m,t,x,T,g,v){const u=r("Link");return s(),p("div",null,[t[13]||(t[13]=l('<h1 id="ubuntu-有望讓你安裝最新-nvidia-linux-驅動更簡單" tabindex="-1">Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單 <a class="header-anchor" href="#ubuntu-有望讓你安裝最新-nvidia-linux-驅動更簡單" aria-label="Permalink to “Ubuntu 有望讓你安裝最新 Nvidia Linux 驅動更簡單”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/03/ubuntugamer_logo_dark-500x250.jpg" alt="Ubuntu Gamers are on the rise -and so is demand for the latest drivers"></p><p><em>Ubuntu 上的遊戲玩家在增長——因而需要最新版驅動</em></p><p><strong>在 Ubuntu 上安裝上游的 NVIDIA 圖形驅動即將變得更加容易。</strong></p><p>Ubuntu 開發者正在考慮構建一個全新的&#39;官方&#39; PPA，以便為桌面用户分發最新的閉源 NVIDIA 二進制驅動。</p><p>該項改變會讓 Ubuntu 遊戲玩家收益，並且<em>不會</em>給其它人造成 OS 穩定性方面的風險。</p><p><strong>僅</strong>當用户明確選擇它時，新的上游驅動將通過這個新 PPA 安裝並更新。其他人將繼續得到並使用更近的包含在 Ubuntu 歸檔中的穩定版 NVIDIA Linux 驅動快照。</p><h3 id="為什麼需要該項目" tabindex="-1">為什麼需要該項目？ <a class="header-anchor" href="#為什麼需要該項目" aria-label="Permalink to “為什麼需要該項目？”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/drivers.jpg" alt="Ubuntu provides drivers – but they’re not the latest"></p><p><em>Ubuntu 提供了驅動——但是它們不是最新的</em></p><p>可以從歸檔中（使用命令列、synaptic，或者通過額外驅動工具）安裝到 Ubuntu 上的閉源 NVIDIA 圖形驅動在大多數情況下都能工作得很好，並且可以輕鬆地處理 Unity 桌面外殼的混染。</p><p>但對於遊戲需求而言，那完全是另外一碼事兒。</p><p>如果你想要將最高幀率和 HD 紋理從最新流行的 Steam 遊戲中壓榨出來，你需要最新的二進制驅動文件。</p><p>驅動越新，越可能支持最新的特性和技術，或者帶有預先打包的遊戲專門的優化和漏洞修復。</p><p>問題在於，在 Ubuntu 上安裝最新 Nvidia Linux 驅動不是件容易的事兒，而且也不具安全保證。</p><p>要填補這個空白，許多由熱心人維護的第三方 PPA 就出現了。由於許多這些 PPA 也發佈了其它實驗性的或者前沿軟件，它們的使用<strong>並不是毫無風險的</strong>。添加一個前沿的 PPA 通常是搞崩整個系統的最快的方式！</p><p>一個解決方法是，讓 Ubuntu 用户安裝最新的專有圖形驅動以滿足對第三方 PPA 的需要，<strong>但是</strong>提供一個安全機制，如果有需要，你可以回滾到穩定版本。</p><h3 id="對全新驅動的需求難以忽視" tabindex="-1">‘對全新驅動的需求難以忽視’ <a class="header-anchor" href="#對全新驅動的需求難以忽視" aria-label="Permalink to “‘對全新驅動的需求難以忽視’”">​</a></h3><blockquote><p>&#39;一個讓Ubuntu用户安全地獲得最新硬件驅動的解決方案出現了。&#39;</p></blockquote><p>‘在快速發展的市場中，對全新驅動的需求正變得難以忽視，用户將想要最新的上游軟件，’卡斯特羅在一封給 Ubuntu 桌面郵件列表的電子郵件中解釋道。</p><p>‘[NVIDIA] 可以毫不費力為 [Windows 10] 用户帶來了不起的體驗。直到我們可以説服 NVIDIA 在 Ubuntu 中做了同樣的工作，這樣我們就可以搞定這一切了。’</p><p>卡斯特羅的“官方的” NVIDIA PPA 方案就是最實現這一目的的最容易的方式。</p><p>遊戲玩家將可以在 Ubuntu 的默認專有軟件驅動工具中選擇接收來自該 PPA 的新驅動，再也不需要它們從網站或維基頁面拷貝並粘貼終端命令了。</p><p>該 PPA 內的驅動將由一個選定的社區成員組成的團隊打包並維護，並受惠於一個名為<strong>自動化測試</strong>的半官方方式。</p><p>就像卡斯特羅自己説的那樣：&#39;人們想要最新的閃光的東西，而不管他們想要做什麼。我們也許也要在其周圍放置一個框架，因此人們可以獲得他們所想要的，而不必破壞他們的計算機。&#39;</p><p><strong>你想要使用這個 PPA 嗎？你怎樣來評估 Ubuntu 上默認 Nvidia 驅動的性能呢？在評論中分享你的想法吧，夥計們！</strong></p><hr>',27)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.omgubuntu.co.uk/2015/08/ubuntu-easy-install-latest-nvidia-linux-drivers"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.omgubuntu.co.uk/2015/08/ubuntu-easy-install-latest-nvidia-linux-drivers",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=n("作者：",-1)),e(u,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[2]||(t[2]=[n("Joey-Elijah Sneddon",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),e(u,{href:"https://github.com/GOLinux"},{default:a(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),e(u,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),e(u,{href:"https://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const N=o(d,[["render",b]]);export{U as __pageData,N as default};
